const repo = "acme/api";
const all: any[] = [];
for (let page = 1; page < 50; page++) {
  const res: any = await tools.list_issues({ repo, state: "open", label: "bug", page });
  const items = Array.isArray(res) ? res : (res?.items ?? res?.issues ?? []);
  if (!items.length) break;
  all.push(...items);
  if (items.length < 50) break;
}
const seen = new Set<number>();
const matches: any[] = [];
let total = 0;
for (const it of all) {
  const n = it.number ?? it.id;
  if (seen.has(n)) continue;
  seen.add(n);
  const d: any = await tools.get_issue({ repo, number: n });
  total++;
  if (d.pull_request) continue;
  const state = d.state;
  const labels = (d.labels ?? []).map((l: any) => (typeof l === "string" ? l : l.name));
  const assignees = d.assignees ?? d.assignee ?? null;
  const noAssignee = assignees === null || (Array.isArray(assignees) && assignees.length === 0);
  const comments = Number(d.comments ?? d.comments_count ?? d.num_comments ?? 0);
  if (state === "open" && labels.includes("bug") && noAssignee && comments > 5) {
    matches.push({ number: n, comments });
  }
}
return { listed: all.length, uniqueFetched: total, count: matches.length, numbers: matches.map(m => m.number) };
